    <a-modal v-model:visible="priceDialogVisible" title="学校价格列表" :width="960" :footer="false" :render-to-body="true" unmount-on-close>
      <a-table :columns="priceColumns" :data="prices" :loading="loading.prices" :pagination="false" :scroll="{ y: 520 }" row-key="id">
