      unmount-on-close
    >
      <div class="status-dialog-body">
        <div class="status-message-panel">
          <span class="status-card-label">说明</span>
          <p>{{ queryLinkDialogDescription }}</p>
        </div>
        <div class="status-grid">
          <div class="status-card-item">
            <span class="status-card-label">站点 UID</span>
            <span class="status-card-value">{{ bootstrapState.currentUserUid || '-' }}</span>
          </div>
          <div class="status-card-item">
            <span class="status-card-label">当前用户</span>
            <span class="status-card-value">{{ bootstrapState.currentUserName || '-' }}</span>
          </div>
        </div>
        <a-form :model="{ pin: queryLinkPin }" layout="vertical">
          <a-form-item :label="hasIssuedQueryLink ? '重设 6 位 PIN 码' : '设置 6 位 PIN 码'">
            <a-input
              v-model="queryLinkPin"
              maxlength="6"
              allow-clear
              :placeholder="hasIssuedQueryLink ? '如需重设，请输入新的 6 位数字 pin 码' : '请输入 6 位数字 pin 码'"
            />
          </a-form-item>
          <a-form-item label="人脸上传专属查询链接">
            <a-textarea
              :model-value="currentQueryLink?.query_url || ''"
              :auto-size="{ minRows: 3, maxRows: 5 }"
              readonly
              placeholder="申请后会在这里显示"
            />
          </a-form-item>
        </a-form>
        <div class="dialog-toolbar">
          <a-button @click="copyQueryLink" :disabled="!currentQueryLink?.query_url">复制链接</a-button>
          <a-space>
            <a-button :loading="queryLinkLoading" @click="refreshQueryLinkCurrent">刷新</a-button>
            <a-button type="primary" :loading="queryLinkSubmitting" @click="issueQueryLink">{{ queryLinkPrimaryActionLabel }}</a-button>
          </a-space>
        </div>
      </div>
    </a-modal>

    <section v-show="activeTab === 'orders'" class="content-card mobile-illustrated-card order-list-card">
      <header class="card-header">
        <div>
          <div class="card-title-row">
            <h2>订单列表</h2>
            <div class="card-title-actions">
              <a-button type="primary" @click="openOrderDialog">添加订单</a-button>
              <a-button type="outline" @click="loadOrders">刷新订单</a-button>
            </div>
          </div>
          <p>插件本地记录会定时同步网关状态，你也可以手动刷新。</p>
        </div>
      </header>
      <div class="order-toolbar">
        <a-input-search
          v-model="orderSearchKeyword"
          allow-clear
          class="order-search-input"
          placeholder="检索学校、账号、平台或追踪号"
        />
        <span class="order-search-summary">共 {{ filteredSortedOrders.length }} 条</span>
      </div>

      <div class="card-table-shell">
        <a-table
          :columns="orderColumns"
          :data="visibleOrders"
          :pagination="false"
          :scroll="isMobile ? { x: 480 } : { x: 1180 }"
          row-key="trace_id"
          :class="{ 'mobile-order-table': isMobile }"
        >
          <template #hostUser="{ record }">
            {{ record.host_display_name || record.host_username || `UID:${record.host_user_uid || 0}` }}
          </template>
          <template #mobileInfo="{ record }">
            <div class="mobile-order-summary">
              <span>学校：{{ record.school_name || '-' }}</span>
              <span>公里数：{{ record.target_km || 0 }}</span>
              <span>类型：{{ record.platform || '-' }}</span>
              <span>审核状态：{{ formatOrderAuditStatus(record.status) }}</span>
              <span>实扣金额：{{ formatOrderCharge(record) }}</span>
              <span v-if="record.status === 'refunded' || Number(record.customer_refunded_cents ?? record.refunded_cents) > 0">累计实退：{{ formatMoney(Number(record.customer_refunded_cents ?? record.refunded_cents ?? 0) / 100) }}</span>
            </div>
          </template>
          <template #charge="{ record }">
            {{ formatOrderCharge(record) }}
          </template>
          <template #status="{ record }">
            <a-tag :color="statusTagColor(record.status)">{{ formatOrderAuditStatus(record.status) }}</a-tag>
          </template>
          <template #statusMessage="{ record }">
            {{ formatOrderStatusMessage(record) }}
          </template>
          <template #updatedAt="{ record }">
            {{ formatDisplayTime(record.updated_at) }}
          </template>
          <template #actions="{ record }">
            <div class="table-actions">
              <a-button v-if="canRefund(record.status)" type="text" status="danger" @click="refundOrder(record)">退款</a-button>
              <a-button v-if="canQueryStatus(record.status)" type="text" @click="openStatusDialog(record)">查状态</a-button>
            </div>
          </template>
        </a-table>
      </div>
      <div v-if="showOrderPagination" class="card-pagination">
        <a-pagination
          :simple="isMobile"
          :total="sortedOrders.length"
          :current="orderPage"
          :page-size="orderPageSize"
          @change="handleOrderPageChange"
        />
      </div>
    </section>

    <a-modal v-model:visible="orderDialogVisible" title="添加订单" :width="560" :footer="false" :render-to-body="true" unmount-on-close>
      <div class="dialog-toolbar">
        <p>学校、平台、公里数与晨跑模式都来自牢大运动统一口径。</p>
        <a-button type="text" :loading="loading.prices" @click="openPriceDialog">查看价格列表</a-button>
      </div>

      <a-form :model="form" layout="vertical" class="order-form">
        <a-form-item field="school_name" label="学校">
          <a-select v-model="form.school_name" allow-search placeholder="请选择或输入学校名称搜索">
            <a-option v-for="school in schools" :key="school.id" :value="school.name">{{ school.name }}</a-option>
          </a-select>
        </a-form-item>
        <a-form-item field="platform" label="平台">
          <a-select v-model="form.platform" :disabled="isPlatformForced" placeholder="请选择平台">
            <a-option v-for="platform in platforms" :key="platform" :value="platform">{{ platform }}</a-option>
          </a-select>
        </a-form-item>
        <a-form-item field="account" label="账号">
          <a-input v-model="form.account" placeholder="手机号或账号" allow-clear />
        </a-form-item>
        <a-form-item field="password" label="密码">
          <a-input-password v-model="form.password" placeholder="密码" allow-clear />
        </a-form-item>
        <a-form-item field="target_km" label="公里数">
          <a-input-number v-model="form.target_km" :min="10" :max="200" :step="0.5" style="width: 100%" />
        </a-form-item>
        <a-form-item label="跑步模式">
          <div class="mode-row">
            <a-switch
              v-model="form.is_morning_run"
              :disabled="Boolean(currentSchoolConfig && !currentSchoolConfig.morning_run_enabled)"
            />
            <a-tag color="#29567f">{{ form.is_morning_run ? '晨跑' : '日常跑' }}</a-tag>
          </div>
        </a-form-item>
        <a-form-item v-if="currentSchoolConfig && displayedEstimatedPrice > 0" label="预计扣费">
          <div class="mode-row">
            <strong style="color: var(--accent-danger); font-size: 18px;">{{ formatMoney(displayedEstimatedPrice) }}</strong>
            <a-tag color="#c6982f">
              {{ priceDisplayTagText }}
            </a-tag>
          </div>
        </a-form-item>
        <a-button type="primary" size="large" long :loading="loading.submit" @click="submitOrder">提交订单</a-button>
      </a-form>
    </a-modal>

    <a-modal
      v-model:visible="statusDialogVisible"
      :title="statusDialogOrder?.trace_id ? `订单状态 | ${statusDialogOrder.trace_id}` : '订单状态'"
      :width="640"
      :footer="false"
      :render-to-body="true"
      unmount-on-close
    >
      <div class="dialog-toolbar">
        <p>这里展示的是牢大运动真实订单状态和当前公里数进度。</p>
        <a-button
          type="primary"
          :loading="statusDialogLoading"
          :disabled="!statusDialogOrder?.trace_id"
          @click="statusDialogOrder?.trace_id && fetchOrderStatusDetail(statusDialogOrder.trace_id, true)"
        >
          重新查询
        </a-button>
      </div>
      <div v-if="statusDialogOrder" class="status-dialog-body">
        <div class="status-grid">
          <div class="status-card-item">
            <span class="status-card-label">追踪号</span>
            <span class="status-card-value monospace-value">{{ statusDialogOrder.trace_id }}</span>
          </div>
          <div class="status-card-item">
            <span class="status-card-label">审核状态</span>
            <a-tag :color="statusTagColor(statusDialogOrder.status)">{{ formatOrderAuditStatus(statusDialogOrder.status) }}</a-tag>
          </div>
          <div class="status-card-item">
            <span class="status-card-label">牢大运动状态</span>
            <a-tag :color="mainStatusTagColor(statusDialogOrder.main_order_status)">
              {{ formatMainOrderStatus(statusDialogOrder.main_order_status) }}
            </a-tag>
          </div>
          <div class="status-card-item">
            <span class="status-card-label">当前进度</span>
            <span class="status-card-value">{{ formatOrderProgress(statusDialogOrder) }}</span>
          </div>
          <div class="status-card-item">
            <span class="status-card-label">学校</span>
            <span class="status-card-value">{{ statusDialogOrder.school_name || '-' }}</span>
          </div>
          <div class="status-card-item">
            <span class="status-card-label">平台</span>
            <span class="status-card-value">{{ statusDialogOrder.platform || '-' }}</span>
          </div>
          <div class="status-card-item">
            <span class="status-card-label">目标公里数</span>
            <span class="status-card-value">{{ formatDistance(statusDialogOrder.main_target_km ?? statusDialogOrder.target_km ?? 0) }} km</span>
          </div>
          <div class="status-card-item">
            <span class="status-card-label">实扣金额</span>
            <span class="status-card-value">{{ formatOrderCharge(statusDialogOrder) }}</span>
          </div>
          <div class="status-card-item">
            <span class="status-card-label">累计实退</span>
            <span class="status-card-value">{{ formatMoney(Number(statusDialogOrder.customer_refunded_cents ?? statusDialogOrder.refunded_cents ?? 0) / 100) }}</span>
          </div>
          <div class="status-card-item">
            <span class="status-card-label">状态更新时间</span>
            <span class="status-card-value">{{ formatDisplayTime(statusDialogOrder.status_query_updated_at || statusDialogOrder.updated_at) }}</span>
          </div>
        </div>
        <div class="status-message-panel">
          <span class="status-card-label">状态说明</span>
          <p>{{ statusDialogMessage || formatOrderStatusMessage(statusDialogOrder) }}</p>
        </div>
      </div>
      <div v-else class="status-message-panel">
        <span class="status-card-label">状态说明</span>
        <p>订单信息不存在</p>
      </div>
    </a-modal>

    <PricingSettings
      v-if="bootstrapState.currentUserUid === 1 && activeTab === 'settings'"
      :current-user-uid="bootstrapState.currentUserUid"
      @saved="handlePricingSaved"
    />
    <TicketPanel
      v-show="activeTab === 'tickets'"
      :orders="orders"
      :current-user-name="bootstrapState.currentUserName"
      :current-user-uid="bootstrapState.currentUserUid"
      :is-mobile="isMobile"
    />
  </div>
</template>

<script setup lang="ts">
import { MoonStar, SunMedium } from 'lucide-vue-next'
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { Message } from '@arco-design/web-vue'
import axios from 'axios'
import TicketPanel from '../components/TicketPanel.vue'
import PricingSettings from '../components/PricingSettings.vue'
import { useTheme } from '../composables/useTheme'
import { getErrorMessage, request, throwApiError } from '../lib/api'

type BootstrapData = {
  appKey: string
  siteName: string
  currentUserName: string
  currentUserUid: number
  currentUserUuid: string
  currentUserMoney: number
  serverTimeRaw: string
  serverTimeLabel: string
}

type PriceRow = {
  id?: string
  school_name: string
  platforms: string[]
  daily_unit_price: number
  morning_unit_price: number
}

type OrderRow = {
  trace_id: string
  source_order_id?: string
  host_user_uid: number
  host_username: string
  host_display_name: string
  host_user_uuid: string
  account?: string
  password?: string
  school_name: string
  platform: string
  target_km: number
  status: string
  status_message: string
  main_order_status?: string
  current_km?: number
  main_target_km?: number
  status_query_updated_at?: string
  price_cents?: number
  refunded_cents?: number
  host_charge_applied?: number | string
  host_charge_amount?: number | string | null
  host_price_cents?: number | null
  host_charge_cents?: number | null
  host_discount_cents?: number | null
  customer_refunded_cents?: number | null
  created_at?: string
  updated_at: string
}

type OrderQueryLinkRow = {
  id: string
  site_id: string
  site_name: string
  host_user_uid: number
  host_username: string
  host_display_name: string
  host_user_uuid: string
  status: string
  remark: string
  access_token: string
  query_url: string
  created_at: string
  updated_at: string
  last_used_at: string
  last_used_ip: string
  use_count: number
}

type SchoolRow = {
  id: string
  name: string
  platform: string
  forcePlatform: boolean
  morning_run_enabled: boolean
  daily_unit_price: number
  morning_unit_price: number
}

type BootstrapPayload = {
  app_key?: string
  site_name?: string
  current_user?: {
    uid?: number | string
    uuid?: string
    username?: string
    display_name?: string
    money?: number | string
  }
  server_time?: string
}

type HostProfilePayload = {
  uid?: number | string
  uuid?: string
  username?: string
  display_name?: string
  money?: number | string
}

type PricesPayload = {
  prices?: Array<Record<string, unknown>>
}

type DashboardTab = 'orders' | 'tickets' | 'settings'

const loading = reactive({
  bootstrap: false,
  submit: false,
  balance: false,
  prices: false,
})

const bootstrapState = reactive<BootstrapData>({
  appKey: '',
  siteName: '',
  currentUserName: '',
  currentUserUid: 0,
  currentUserUuid: '',
  currentUserMoney: 0,
  serverTimeRaw: '',
  serverTimeLabel: '',
})

const schools = ref<SchoolRow[]>([])
const platforms = ref<string[]>([])
const prices = ref<PriceRow[]>([])
const orders = ref<OrderRow[]>([])
const priceConflictCents = ref<number | null>(null)
const priceDialogVisible = ref(false)
const orderDialogVisible = ref(false)
const statusDialogVisible = ref(false)
const statusDialogLoading = ref(false)
const statusDialogOrder = ref<OrderRow | null>(null)
const statusDialogMessage = ref('')
const queryLinkDialogVisible = ref(false)
const queryLinkLoading = ref(false)
const queryLinkSubmitting = ref(false)
const queryLinkPin = ref('')
const currentQueryLink = ref<OrderQueryLinkRow | null>(null)
const noticeDialogVisible = ref(true)
const activeTab = ref<DashboardTab>('orders')
const isMobile = ref(false)
const orderSearchKeyword = ref('')
const orderPage = ref(1)
const mobileOrderPageSize = 4
const desktopOrderPageSize = 10

const form = reactive({
  school_name: '',
  platform: '',
  account: '',
  password: '',
  target_km: 10,
  is_morning_run: false,
})

const connected = computed(() => Boolean(bootstrapState.appKey))
const isAdminUser = computed(() => bootstrapState.currentUserUid === 1)
const hasIssuedQueryLink = computed(() => Boolean(currentQueryLink.value?.query_url?.trim()))
const queryLinkActionLabel = computed(() => hasIssuedQueryLink.value ? '查看人脸上传专属链接/重设 pin' : '申请人脸上传专属查单链接')
const queryLinkDialogTitle = computed(() => hasIssuedQueryLink.value ? '查看人脸上传专属链接 / 重设 PIN' : '申请人脸上传专属查单链接')
const queryLinkPrimaryActionLabel = computed(() => hasIssuedQueryLink.value ? '重设 PIN' : '申请人脸上传专属链接')
const queryLinkDialogDescription = computed(() => {
  if (hasIssuedQueryLink.value) {
    return '这里展示的是你当前站点账号已经申请好的人脸上传专属查单链接。人脸上传专属查单链接必须配合 6 位 PIN 才能使用；如果你想更换 PIN，直接在下方输入新的 6 位 PIN 并提交即可。'
  }
  return '这里可以申请你当前站点账号的人脸上传专属查单链接。人脸上传专属查单链接只有设置了 6 位 PIN 之后才能使用；申请成功后，会返回你自己的人脸上传专属查询链接。'
})
const { toggleTheme, isDark } = useTheme()
const isRetrying = computed(() => loading.bootstrap || loading.balance)
const welcomeTitle = computed(() => {
  const userName = bootstrapState.currentUserName?.trim() || '测试站用户'
  const siteName = bootstrapState.siteName?.trim()
  return siteName
    ? `欢迎你，“${userName}”，来到「${siteName}」的“牢大运动😋”对接页面`
    : `欢迎你，“${userName}”，来到“牢大运动😋”对接页面`
})
const syncBadgeLabel = computed(() => formatSyncBadgeTime(bootstrapState.serverTimeRaw))
const currentSchoolConfig = computed(() => {
  return schools.value.find((item) => item.name === form.school_name) ?? null
})
const isPlatformForced = computed(() => Boolean(currentSchoolConfig.value?.forcePlatform && currentSchoolConfig.value?.platform))
const estimatedPrice = computed(() => {
  if (!currentSchoolConfig.value || !form.target_km) {
    return 0
  }
  const unitPrice = form.is_morning_run
    ? Number(currentSchoolConfig.value.morning_unit_price || 0)
    : Number(currentSchoolConfig.value.daily_unit_price || 0)
  return unitPrice * Number(form.target_km || 0)
})
const displayedEstimatedPrice = computed(() => {
  if (priceConflictCents.value !== null) {
    return priceConflictCents.value / 100
  }
  return estimatedPrice.value
})
const priceDisplayTagText = computed(() => {
  if (priceConflictCents.value !== null) {
    return '已按牢大运动最新报价更新'
  }
  const unitPrice = form.is_morning_run
    ? currentSchoolConfig.value?.morning_unit_price ?? 0
    : currentSchoolConfig.value?.daily_unit_price ?? 0
  return `单价：${formatUnitPrice(unitPrice)} 元/km`
})

function formatUnitPrice(value: number) {
  return Number(value.toFixed(8)).toString()
}

const priceColumns = [
  { title: '学校', dataIndex: 'school_name', width: 180 },
  { title: '平台', slotName: 'platforms', width: 180 },
  { title: '日常跑单价', slotName: 'dailyUnitPrice', width: 120 },
  { title: '晨跑单价', slotName: 'morningUnitPrice', width: 120 },
]

const orderColumns = computed(() => {
  if (isMobile.value) {
    return [
      { title: '账号', dataIndex: 'account', width: 130 },
      { title: '密码', dataIndex: 'password', width: 110 },
      { title: '信息', slotName: 'mobileInfo', width: 220 },
      { title: '操作', slotName: 'actions', width: 120 },
    ]
  }

  const desktopColumns = [
    { title: '账号', dataIndex: 'account', width: 150 },
    { title: '密码', dataIndex: 'password', width: 130 },
    { title: '公里数', dataIndex: 'target_km', width: 90 },
    { title: '学校', dataIndex: 'school_name', width: 120 },
    { title: '平台', dataIndex: 'platform', width: 110 },
    { title: '实扣金额', slotName: 'charge', width: 120 },
    { title: '审核状态', slotName: 'status', width: 130 },
    { title: '状态说明', slotName: 'statusMessage', width: 180 },
    { title: '更新时间', slotName: 'updatedAt', width: 180 },
    { title: '操作', slotName: 'actions', width: 220 },
  ]

  if (isAdminUser.value) {
    desktopColumns.unshift({ title: '下单用户', slotName: 'hostUser', width: 180 })
  }

  return desktopColumns
})

function parseOrderTime(value: string | undefined) {
  if (!value) {
    return 0
  }
  const timestamp = new Date(value).getTime()
  return Number.isNaN(timestamp) ? 0 : timestamp
}

const orderPageSize = computed(() => (isMobile.value ? mobileOrderPageSize : desktopOrderPageSize))

const sortedOrders = computed(() => {
  return [...orders.value].sort((left, right) => {
    const rightTime = parseOrderTime(right.created_at || right.updated_at)
    const leftTime = parseOrderTime(left.created_at || left.updated_at)
    return rightTime - leftTime
  })
})

function normalizeSearchText(value: string | number | undefined) {
  return String(value || '').trim().toLowerCase()
}

const filteredSortedOrders = computed(() => {
  const keyword = normalizeSearchText(orderSearchKeyword.value)
  if (!keyword) {
    return sortedOrders.value
  }
  return sortedOrders.value.filter((order) => {
    return [
      order.account,
      order.school_name,
      order.platform,
      order.trace_id,
    ].some((field) => normalizeSearchText(field).includes(keyword))
  })
})

const visibleOrders = computed(() => {
  const start = (orderPage.value - 1) * orderPageSize.value
  return filteredSortedOrders.value.slice(start, start + orderPageSize.value)
})

const showOrderPagination = computed(() => filteredSortedOrders.value.length > orderPageSize.value)

function statusTagColor(status: string) {
  if (status === 'approved') return '#3d6b57'
  if (status === 'pending_delivery' || status === 'pending_review') return '#c6982f'
  if (status === 'refunded') return '#8e4b3b'
  if (status === 'rejected') return '#8e4b3b'
  return '#29567f'
}

function formatOrderAuditStatus(status: string) {
  if (status === 'pending_review') return '待审核'
  if (status === 'rejected') return '已驳回'
  if (status === 'approved') return '已通过'
  if (status === 'refunded') return '已退款'
  if (status === 'pending_delivery') return '待送达'
  return status || '-'
}

function mainStatusTagColor(status: string | undefined) {
  const normalized = String(status || '').trim()
  if (!normalized) return '#86909c'
  if (normalized === 'completed') return '#3d6b57'
  if (normalized === 'in_progress') return '#29567f'
  if (normalized === 'not_started' || normalized === 'pending' || normalized === 'pended') return '#c6982f'
  if (normalized === 'paused') return '#d9912b'
  if (normalized === 'refunded') return '#8e4b3b'
  return '#4e5969'
}

function formatMainOrderStatus(status: string | undefined) {
  const normalized = String(status || '').trim()
  if (!normalized) return '未查询'
  if (normalized === 'not_started') return '未开始'
  if (normalized === 'pending' || normalized === 'pended') return '待开始'
  if (normalized === 'in_progress') return '进行中'
  if (normalized === 'completed') return '已完成'
  if (normalized === 'paused') return '已暂停'
  if (normalized === 'refunded') return '已退款'
  if (normalized === 'cancelled') return '已取消'
  return normalized
}

function formatDistance(value: number | string | undefined) {
  const numeric = Number(value || 0)
  if (!Number.isFinite(numeric)) {
    return '0'
  }
  return Number.isInteger(numeric) ? String(numeric) : numeric.toFixed(2).replace(/\.?0+$/, '')
}

function formatOrderProgress(order: OrderRow) {
  const targetKm = Number(order.main_target_km ?? order.target_km ?? 0)
  if (!Number.isFinite(targetKm) || targetKm <= 0) {
    return '-'
  }
  const currentKm = Number(order.current_km ?? 0)
  return `${formatDistance(currentKm)} / ${formatDistance(targetKm)} km`
}

function canRefund(status: string) {
  return status === 'pending_review'
}

function canQueryStatus(status: string) {
  return status === 'approved'
}

function formatDisplayTime(value: string) {
  if (!value) return '-'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return value
  return date.toLocaleString('zh-CN', { hour12: false })
}

function formatSyncBadgeTime(value: string) {
  if (!value || value === '-') return '-'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return value
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  const hours = String(date.getHours()).padStart(2, '0')
  const minutes = String(date.getMinutes()).padStart(2, '0')
  return `${month}-${day} ${hours}:${minutes}`
}

function formatMoney(value: number) {
  return `¥${Number(value || 0).toFixed(2)}`
}

function formatOrderCharge(order: OrderRow) {
  if (Number(order.host_charge_applied) === 1 && order.host_charge_amount != null) {
    return formatMoney(Number(order.host_charge_amount))
  }
  const cents = order.host_charge_cents
  return cents == null ? '-' : formatMoney(Number(cents) / 100)
}

function formatOrderStatusMessage(order: OrderRow) {
  const refundedCents = Number(order.customer_refunded_cents ?? order.refunded_cents ?? 0)
  if (refundedCents > 0 || (order.status === 'refunded' && order.customer_refunded_cents != null)) {
    return `累计实退：${formatMoney(refundedCents / 100)}`
  }
  if (String(order.status || '') === 'approved' && order.status_query_updated_at) {
    return `牢大运动状态更新时间：${formatDisplayTime(order.status_query_updated_at)}`
  }
  return order.status_message || '-'
}

function toPriceCents(value: number) {
  return Math.round(Number(value || 0) * 100)
}

function handleOrderPageChange(page: number) {
  orderPage.value = page
}

function updateViewportState() {
  isMobile.value = window.innerWidth <= 640
}

async function bootstrap() {
  loading.bootstrap = true
  console.info('[PLUGIN-DEBUG] bootstrap:start')
  try {
    const data = await request<BootstrapPayload>('bootstrap')
    const payload = data.data || {}
    const currentUser = payload.current_user || {}
    bootstrapState.appKey = payload.app_key || ''
    bootstrapState.siteName = payload.site_name || ''
    bootstrapState.currentUserName = currentUser.display_name || currentUser.username || '未登录'
    bootstrapState.currentUserUid = Number(currentUser.uid || 0)
    bootstrapState.currentUserUuid = String(currentUser.uuid || '')
    bootstrapState.currentUserMoney = Number(currentUser.money || 0)
    bootstrapState.serverTimeRaw = String(payload.server_time || '')
    bootstrapState.serverTimeLabel = formatDisplayTime(payload.server_time || '')
    console.info('[PLUGIN-DEBUG] bootstrap:resolved', {
      siteName: bootstrapState.siteName,
      currentUserUid: bootstrapState.currentUserUid,
      currentUserName: bootstrapState.currentUserName,
    })
    await Promise.all([loadCatalog(), loadOrders(), loadQueryLinkCurrent(false)])
  } catch (error) {
    Message.error(getErrorMessage(error, '初始化失败'))
    console.error(error)
  } finally {
    loading.bootstrap = false
  }
}

async function loadHostBalance(showMessage = false) {
  loading.balance = true
  try {
    const result = await request<HostProfilePayload>('host_profile')
    const payload = result.data || {}
    bootstrapState.currentUserUid = Number(payload.uid || 0)
    bootstrapState.currentUserUuid = String(payload.uuid || '')
    bootstrapState.currentUserMoney = Number(payload.money || 0)
    if (!bootstrapState.currentUserName) {
      bootstrapState.currentUserName = payload.display_name || payload.username || '未登录'
    }
    if (showMessage) {
      Message.success(`当前余额：${formatMoney(bootstrapState.currentUserMoney)}`)
    }
  } catch (error) {
    Message.error(getErrorMessage(error, '余额读取失败'))
    console.error(error)
  } finally {
    loading.balance = false
  }
}

async function loadCatalog() {
  const [schoolRes, platformRes] = await Promise.all([
    request('schools'),
    request('platforms'),
  ])
  const schoolCatalog = Array.isArray(schoolRes.data) ? schoolRes.data : []
  schools.value = schoolCatalog.map((item: Record<string, unknown>) => ({
    id: String(item.id || ''),
    name: String(item.name || ''),
    platform: String(item.platform || ''),
    forcePlatform: Boolean(item.forcePlatform),
    morning_run_enabled: Boolean(item.morningRunEnabled),
    daily_unit_price: Number(item.daily_unit_price ?? item.dailyUnitPrice ?? 0),
    morning_unit_price: Number(item.morning_unit_price ?? item.morningUnitPrice ?? 0),
  }))
  platforms.value = Array.isArray(platformRes.data) ? platformRes.data.map((item: unknown) => String(item)) : []
  if (!form.school_name && schools.value[0]) form.school_name = schools.value[0].name
  syncPlatformWithSchool()
}

async function loadPriceList(forceRefresh = false) {
  if (!forceRefresh && prices.value.length > 0) {
    return
  }

  loading.prices = true
  try {
    const result = await request<PricesPayload>('prices')
    const priceRows = Array.isArray(result.data?.prices) ? result.data.prices : []
    prices.value = priceRows.map((item: Record<string, unknown>) => ({
      id: String(item.id || item.school_name || ''),
      school_name: String(item.school_name || ''),
      platforms: Array.isArray(item.platforms) ? item.platforms.map((platform) => String(platform)) : [],
      daily_unit_price: Number(item.daily_unit_price ?? 0),
      morning_unit_price: Number(item.morning_unit_price ?? 0),
    }))
  } finally {
    loading.prices = false
  }
}

async function handlePricingSaved() {
  if (bootstrapState.currentUserUid !== 1) return
  priceConflictCents.value = null
  schools.value = []
  prices.value = []
  try {
    await Promise.all([loadCatalog(), loadPriceList(true)])
  } catch (error) {
    Message.error(getErrorMessage(error, '倍率已保存，但最新学校和价格读取失败，请重试'))
  }
}

async function openPriceDialog() {
  try {
    await loadPriceList(true)
    priceDialogVisible.value = true
  } catch (error) {
    Message.error(getErrorMessage(error, '价格列表读取失败'))
    console.error(error)
  }
}

async function openOrderDialog() {
  orderDialogVisible.value = true
  priceConflictCents.value = null
  try {
    await refreshCatalogSnapshot(false)
  } catch (error) {
    console.error(error)
  }
}

async function retryDashboard() {
  await bootstrap()
  await loadHostBalance(false)
}

async function loadQueryLinkCurrent(showError = true) {
  queryLinkLoading.value = true
  try {
    const result = await request<OrderQueryLinkRow | null>('order_query_link_current')
    currentQueryLink.value = (result.data as OrderQueryLinkRow | null) || null
  } catch (error) {
    if (showError) {
      Message.error(getErrorMessage(error, '查单链接读取失败'))
    }
    console.error(error)
  } finally {
    queryLinkLoading.value = false
  }
}

async function refreshQueryLinkCurrent() {
  await loadQueryLinkCurrent(true)
}

async function openQueryLinkDialog() {
  queryLinkDialogVisible.value = true
  queryLinkPin.value = ''
  await loadQueryLinkCurrent()
}

async function issueQueryLink() {
  if (!/^\d{6}$/.test(queryLinkPin.value.trim())) {
    Message.warning('pin 必须为 6 位数字')
    return
  }
  queryLinkSubmitting.value = true
  const hadIssuedBefore = hasIssuedQueryLink.value
  try {
    const result = await request<OrderQueryLinkRow>('order_query_link_issue', 'post', {
      pin: queryLinkPin.value.trim(),
    })
    currentQueryLink.value = (result.data as OrderQueryLinkRow) || null
    Message.success(result.message || (hadIssuedBefore ? 'PIN 已重设' : '人脸上传专属查单链接已生成'))
    queryLinkPin.value = ''
  } catch (error) {
    Message.error(getErrorMessage(error, '查单链接生成失败'))
    console.error(error)
  } finally {
    queryLinkSubmitting.value = false
  }
}

async function copyQueryLink() {
  const value = currentQueryLink.value?.query_url?.trim()
  if (!value) {
    return
  }
  try {
    await navigator.clipboard.writeText(value)
    Message.success('查单链接已复制')
  } catch (error) {
    Message.error('复制失败')
    console.error(error)
  }
}

function syncPlatformWithSchool() {
  if (!platforms.value.length) {
    form.platform = currentSchoolConfig.value?.platform || ''
    return
  }
  const currentSchool = currentSchoolConfig.value
  if (!currentSchool) {
    if (!platforms.value.includes(form.platform)) {
      form.platform = platforms.value[0]
    }
    return
  }
  if (currentSchool.forcePlatform && currentSchool.platform) {
    form.platform = currentSchool.platform
    return
  }
  if (currentSchool.platform && !form.platform) {
    form.platform = currentSchool.platform
    return
  }
  if (!platforms.value.includes(form.platform)) {
    form.platform = currentSchool.platform && platforms.value.includes(currentSchool.platform)
      ? currentSchool.platform
      : platforms.value[0]
  }
}

async function refreshCatalogSnapshot(silent = true) {
  try {
    await loadCatalog()
  } catch (error) {
    console.error(error)
    if (!silent) {
      Message.error(getErrorMessage(error, '学校和价格读取失败'))
    }
  }
}

async function loadOrders() {
  console.info('[PLUGIN-DEBUG] orders:load:start', {
    currentUserUid: bootstrapState.currentUserUid,
    currentUserName: bootstrapState.currentUserName,
  })
  const result = await request<OrderRow[]>('orders')
  orders.value = Array.isArray(result.data) ? result.data : []
  console.info('[PLUGIN-DEBUG] orders:load:finish', {
    count: orders.value.length,
    firstTraceId: orders.value[0]?.trace_id,
    firstStatus: orders.value[0]?.status,
    firstMainStatus: orders.value[0]?.main_order_status,
  })
}

function scheduleOrderStatusPolling(traceId: string, maxAttempts = 90) {
  let attempts = 0
  const tick = async () => {
    attempts += 1
    try {
      const result = await request('order_status', 'get', { trace_id: traceId })
      const order = (result.data as { order?: OrderRow } | undefined)?.order
      await loadOrders()
      if (order?.status && order.status !== 'pending_delivery') {
        if (order.status !== 'pending_review') {
          await loadHostBalance(false)
        }
        return
      }
      if (attempts < maxAttempts) {
        window.setTimeout(tick, Math.max(1500, Number(result.next_poll_after_ms || 3000)))
      }
    } catch (error) {
      console.error(error)
      if (attempts < maxAttempts) {
        window.setTimeout(tick, 3000)
      }
    }
  }
  window.setTimeout(tick, 1600)
}

async function submitOrder() {
  if (!currentSchoolConfig.value) {
    Message.warning('请先刷新学校和价格后再提交订单')
    return
  }
  if (!form.school_name || !form.platform || !form.account || !form.password) {
    Message.warning('请先完整填写学校、平台、账号、密码和公里数')
    return
  }
  if (Number(form.target_km) < 10 || Number(form.target_km) > 200) {
    Message.warning('公里数范围需在 10（含）到 200（含）之间')
    return
  }
  loading.submit = true
  try {
    const currentEstimatedPrice = displayedEstimatedPrice.value
    await loadHostBalance(false)
    if (currentEstimatedPrice > Number(bootstrapState.currentUserMoney || 0)) {
      Message.warning(`站点余额不足，当前余额 ${formatMoney(bootstrapState.currentUserMoney)}，预计扣费 ${formatMoney(currentEstimatedPrice)}`)
      return
    }

    const result = await request('create_order', 'post', {
      ...form,
      expected_price_cents: toPriceCents(currentEstimatedPrice),
      run_mode_enabled: true,
      run_mode_text: form.is_morning_run ? '晨跑' : '日常跑',
    })
    if (!result.trace_id) {
      throwApiError(result, '下单未返回 trace_id')
    }
    Message.success(result.message ? `${result.message}：${result.trace_id}` : `提交成功：${result.trace_id}`)
    await Promise.all([loadOrders(), loadHostBalance()])
    orderDialogVisible.value = false
    scheduleOrderStatusPolling(String(result.trace_id))
  } catch (error) {
    const errorPayload = axios.isAxiosError(error)
      ? error.response?.data
      : (error as { response?: { data?: { code?: number; host_price_cents?: number; price_cents?: number; data?: { host_price_cents?: number; price_cents?: number } } } })?.response?.data
    if (Number(errorPayload?.code || 0) === 409) {
      const latestPriceCents = Number(errorPayload?.host_price_cents ?? errorPayload?.data?.host_price_cents ?? errorPayload?.price_cents ?? errorPayload?.data?.price_cents ?? 0)
      if (latestPriceCents > 0) {
        priceConflictCents.value = latestPriceCents
        Message.warning(`牢大运动价格已更新，当前最新价格为 ${formatMoney(latestPriceCents / 100)}，请重新确认后提交`)
      } else {
        Message.warning(getErrorMessage(error, '提交失败'))
      }
      await loadHostBalance(false)
      return
    }
    Message.error(getErrorMessage(error, '提交失败'))
    console.error(error)
  } finally {
    loading.submit = false
  }
}

function openStatusDialog(order: OrderRow) {
  if (!canQueryStatus(order.status)) {
    return
  }
  statusDialogOrder.value = { ...order }
  statusDialogMessage.value = ''
  statusDialogVisible.value = true
  void fetchOrderStatusDetail(order.trace_id, false)
}

async function fetchOrderStatusDetail(traceId: string, showSuccessMessage: boolean) {
  statusDialogLoading.value = true
  try {
    console.info('[PLUGIN-DEBUG] order-status:refresh:start', { traceId })
    const result = await request<{ order?: OrderRow }>('order_status', 'get', { trace_id: traceId })
    const latestOrder = result.data?.order
    if (latestOrder) {
      statusDialogOrder.value = { ...latestOrder }
      const currentIndex = orders.value.findIndex((item) => item.trace_id === latestOrder.trace_id)
      if (currentIndex >= 0) {
        const nextOrders = [...orders.value]
        nextOrders.splice(currentIndex, 1, latestOrder)
        orders.value = nextOrders
      }
    }
    statusDialogMessage.value = result.message || latestOrder?.status_message || '状态已刷新'
    if (showSuccessMessage) {
      Message.success(statusDialogMessage.value)
    }
  } catch (error) {
    const message = getErrorMessage(error, '状态刷新失败')
    statusDialogMessage.value = message
    Message.error(message)
    console.error(error)
  } finally {
    statusDialogLoading.value = false
  }
}

async function refundOrder(order: OrderRow) {
  if (!canRefund(order.status)) {
    return
  }
  try {
    await request('refund_order', 'post', { trace_id: order.trace_id })
    Message.success('退款成功，实际退款金额以订单累计实退为准')
    await Promise.all([loadOrders(), loadHostBalance(false)])
  } catch (error) {
    Message.error(getErrorMessage(error, '退款失败'))
    console.error(error)
  }
}

onMounted(() => {
  updateViewportState()
  window.addEventListener('resize', updateViewportState)
  bootstrap()
})

onBeforeUnmount(() => {
  window.removeEventListener('resize', updateViewportState)
})

watch(() => form.school_name, () => {
  priceConflictCents.value = null
  syncPlatformWithSchool()
  if (form.is_morning_run && currentSchoolConfig.value && !currentSchoolConfig.value.morning_run_enabled) {
    form.is_morning_run = false
  }
})

watch(() => [form.platform, form.target_km, form.is_morning_run], () => {
  priceConflictCents.value = null
})

watch(isAdminUser, (isAdmin) => {
  if (!isAdmin && activeTab.value === 'settings') activeTab.value = 'orders'
})

watch(orderSearchKeyword, () => {
  orderPage.value = 1
})

watch([orders, isMobile, orderSearchKeyword], () => {
  const totalPages = Math.max(1, Math.ceil(filteredSortedOrders.value.length / orderPageSize.value))
  if (orderPage.value > totalPages) {
    orderPage.value = totalPages
  }
})
