<template>
  <section class="content-card ticket-panel mobile-illustrated-card ticket-list-card">
    <header class="card-header">
      <div>
        <div class="card-title-row">
          <h2>工单列表</h2>
          <div class="ticket-title-actions">
            <a-button type="primary" @click="openCreateDialog">提交工单</a-button>
            <a-button type="outline" :loading="loading.list" @click="loadTickets">刷新工单</a-button>
          </div>
        </div>
        <p>普通用户只会看到自己上报的工单，关联订单时仅允许选择自己可见的订单。</p>
      </div>
    </header>

    <div class="card-table-shell">
      <a-table :columns="ticketColumns" :data="visibleTickets" :loading="loading.list" :pagination="false" :scroll="{ x: 980 }" row-key="id">
        <template #uploader="{ record }">
          {{ record.source_host_display_name || record.source_host_username || `UID:${record.source_host_user_uid || 0}` }}
        </template>
        <template #linkedOrder="{ record }">
          {{ record.source_trace_id || record.order_id || record.source_order_id || '-' }}
        </template>
        <template #status="{ record }">
          <a-tag :color="statusTagColor(record.status)">{{ record.status || '-' }}</a-tag>
        </template>
        <template #updatedAt="{ record }">
          {{ formatDisplayTime(record.last_message_at || record.updated_at) }}
        </template>
        <template #actions="{ record }">
          <a-button type="text" @click="openTicketDetail(record)">查看详情</a-button>
        </template>
      </a-table>
    </div>
    <div v-if="showTicketPagination" class="card-pagination">
      <a-pagination
        simple
        :total="tickets.length"
        :current="ticketPage"
        :page-size="mobileTicketPageSize"
        @change="handleTicketPageChange"
      />
    </div>

    <a-modal v-model:visible="createVisible" title="提交工单" :width="640" :footer="false" :render-to-body="true" unmount-on-close>
      <div class="ticket-create-grid">
      <a-form :model="form" layout="vertical" class="ticket-form">
        <a-form-item field="linked_trace_id" label="关联订单">
          <a-select v-model="form.linked_trace_id" allow-clear allow-search placeholder="可选，选择自己上传的订单">
            <a-option
              v-for="order in props.orders"
              :key="order.trace_id"
              :value="order.trace_id"
            >
              {{ formatOrderOption(order) }}
            </a-option>
          </a-select>
        </a-form-item>
        <a-form-item field="fault_type" label="异常类型">
          <a-select v-model="form.fault_type" placeholder="请选择异常类型">
            <a-option v-for="item in faultTypeOptions" :key="item" :value="item">{{ item }}</a-option>
          </a-select>
        </a-form-item>
        <a-form-item field="account" label="账号">
          <a-input v-model="form.account" placeholder="可手填，不关联订单时建议填写" allow-clear />
        </a-form-item>
        <a-form-item field="password" label="密码">
          <a-input-password v-model="form.password" placeholder="可选" allow-clear />
        </a-form-item>
        <a-form-item field="school" label="学校">
          <a-input v-model="form.school" placeholder="可手填，不关联订单时建议填写" allow-clear />
        </a-form-item>
        <a-form-item field="message" label="问题描述">
          <a-textarea v-model="form.message" :max-length="500" :auto-size="{ minRows: 4, maxRows: 6 }" placeholder="请描述具体问题" />
        </a-form-item>
        <div class="ticket-create-actions">
          <a-button type="primary" :loading="loading.create" @click="createTicket">提交工单</a-button>
        </div>
      </a-form>
      </div>
    </a-modal>

    <a-modal v-model:visible="detailVisible" title="工单详情" :width="860" :footer="false" :render-to-body="true" unmount-on-close>
      <template v-if="activeTicket">
        <a-descriptions :column="2" bordered class="ticket-detail-meta">
          <a-descriptions-item label="工单ID">{{ activeTicket.id }}</a-descriptions-item>
          <a-descriptions-item label="状态">{{ activeTicket.status || '-' }}</a-descriptions-item>
          <a-descriptions-item label="异常类型">{{ activeTicket.fault_type || '-' }}</a-descriptions-item>
          <a-descriptions-item label="关联订单">{{ activeTicket.source_trace_id || activeTicket.order_id || activeTicket.source_order_id || '-' }}</a-descriptions-item>
          <a-descriptions-item label="账号">{{ activeTicket.account || '-' }}</a-descriptions-item>
          <a-descriptions-item label="学校">{{ activeTicket.school || '-' }}</a-descriptions-item>
        </a-descriptions>

        <a-spin :loading="loading.detail" style="width: 100%;">
        <div class="conversation-box">
          <div v-if="messages.length" class="conversation-list">
            <div
              v-for="item in messages"
              :key="item.id || `${item.sender_role}-${item.created_at}-${item.message}`"
              class="conversation-item"
              :class="`role-${item.sender_role || 'system'}`"
            >
              <div class="conversation-header">
                <span>{{ item.sender_name || item.sender_role || '系统' }}</span>
                <span>{{ formatDisplayTime(item.created_at || '') }}</span>
              </div>
              <div class="conversation-message">{{ item.message || '-' }}</div>
            </div>
          </div>
          <a-empty v-else description="暂无对话记录" />
        </div>
        </a-spin>

        <a-textarea v-model="replyMessage" :auto-size="{ minRows: 4, maxRows: 6 }" placeholder="输入回复内容" :disabled="activeTicket.status === '完结'" />
        <div class="ticket-detail-actions">
          <a-button @click="reloadDetail">刷新</a-button>
          <a-button type="primary" :loading="loading.reply" :disabled="activeTicket.status === '完结'" @click="replyTicket">
            发送回复
          </a-button>
        </div>
      </template>
    </a-modal>
  </section>
</template>

<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { computed } from 'vue'
import { Message } from '@arco-design/web-vue'
import { getErrorMessage, request } from '../lib/api'

type OrderRow = {
  trace_id: string
  source_order_id?: string
  account?: string
  school_name?: string
}

type TicketRow = {
  id: string
  order_id?: string
  fault_type?: string
  account?: string
  school?: string
  status?: string
  updated_at?: string
  last_message_at?: string
  source_trace_id?: string
  source_order_id?: string
  source_host_user_uid?: number
  source_host_username?: string
  source_host_display_name?: string
}

type TicketMessage = {
  id?: string
  sender_role?: string
  sender_name?: string
  message?: string
  created_at?: string
}

const props = defineProps<{
  orders: OrderRow[]
  currentUserUid: number
  currentUserName: string
  isMobile: boolean
}>()

const loading = reactive({
  list: false,
  create: false,
  detail: false,
  reply: false,
})

const faultTypeOptions = ['账密错误', '学校错误', '缺少人脸', '人脸错误', '账号封禁', '他人登录', '双线下单']

const form = reactive({
  linked_trace_id: '',
  fault_type: '账密错误',
  account: '',
  password: '',
  school: '',
  message: '',
})

const tickets = ref<TicketRow[]>([])
const createVisible = ref(false)
const detailVisible = ref(false)
const activeTicket = ref<TicketRow | null>(null)
const messages = ref<TicketMessage[]>([])
const replyMessage = ref('')
const ticketPage = ref(1)
const mobileTicketPageSize = 4

const ticketColumns = [
  { title: '工单ID', dataIndex: 'id', width: 180 },
  { title: '上传人', slotName: 'uploader', width: 160 },
  { title: '关联订单', slotName: 'linkedOrder', width: 200 },
  { title: '异常类型', dataIndex: 'fault_type', width: 120 },
  { title: '状态', slotName: 'status', width: 110 },
  { title: '最后更新', slotName: 'updatedAt', width: 180 },
  { title: '操作', slotName: 'actions', width: 160 },
]

const visibleTickets = computed(() => {
  if (!props.isMobile) {
    return tickets.value
  }
  const start = (ticketPage.value - 1) * mobileTicketPageSize
  return tickets.value.slice(start, start + mobileTicketPageSize)
})

const showTicketPagination = computed(() => props.isMobile && tickets.value.length > mobileTicketPageSize)

function resetCreateForm() {
  form.linked_trace_id = ''
  form.fault_type = '账密错误'
  form.account = ''
  form.password = ''
  form.school = ''
  form.message = ''
}

function openCreateDialog() {
  createVisible.value = true
}

function handleTicketPageChange(page: number) {
  ticketPage.value = page
}

function formatDisplayTime(value: string) {
  if (!value) return '-'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return value
  return date.toLocaleString('zh-CN', { hour12: false })
}

function formatOrderOption(order: OrderRow) {
  return [order.trace_id, order.school_name || '', order.account || ''].filter(Boolean).join(' | ')
}

function statusTagColor(status?: string) {
  if (status === '待处理') return '#c6982f'
  if (status === '处理中') return '#29567f'
  if (status === '完结') return '#3d6b57'
  return '#9a6a2a'
}

async function loadTickets() {
  if (props.currentUserUid <= 0) return
  loading.list = true
  try {
    const result = await request<TicketRow[]>('tickets')
    tickets.value = Array.isArray(result.data) ? result.data : []
  } catch (error) {
    Message.error(getErrorMessage(error, '工单读取失败'))
  } finally {
    loading.list = false
  }
}

async function openTicketDetail(row: TicketRow) {
  detailVisible.value = true
  activeTicket.value = { ...row }
  replyMessage.value = ''
  await reloadDetail()
}

async function reloadDetail() {
  if (!activeTicket.value?.id) return
  loading.detail = true
  try {
    const result = await request<{ ticket?: TicketRow; messages?: TicketMessage[] }>('ticket_detail', 'get', {
      ticket_id: activeTicket.value.id,
    })
    const payload = result.data || {}
    activeTicket.value = payload.ticket ? { ...payload.ticket } : activeTicket.value
    messages.value = Array.isArray(payload.messages) ? payload.messages : []
  } catch (error) {
    Message.error(getErrorMessage(error, '工单详情读取失败'))
  } finally {
    loading.detail = false
  }
}

async function reloadDetailUntilMessage(expectedMessage: string, maxAttempts = 25) {
  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    await reloadDetail()
    if (!expectedMessage || messages.value.some((item) => (item.message || '').includes(expectedMessage))) {
      return
    }
    await new Promise((resolve) => window.setTimeout(resolve, 1000))
  }
}

async function createTicket() {
  if (!form.fault_type || !form.message.trim()) {
    Message.warning('异常类型和问题描述不能为空')
    return
  }
  loading.create = true
  try {
    await request('create_ticket', 'post', {
      linked_trace_id: form.linked_trace_id,
      fault_type: form.fault_type,
      account: form.account,
      password: form.password,
      school: form.school,
      message: form.message,
    })
    Message.success('工单创建成功')
    resetCreateForm()
    createVisible.value = false
    await loadTickets()
  } catch (error) {
    Message.error(getErrorMessage(error, '工单创建失败'))
  } finally {
    loading.create = false
  }
}

async function replyTicket() {
  if (!activeTicket.value?.id || !replyMessage.value.trim()) {
    Message.warning('回复内容不能为空')
    return
  }
  loading.reply = true
  try {
    const sentMessage = replyMessage.value.trim()
    await request('reply_ticket', 'post', {
      ticket_id: activeTicket.value.id,
      message: sentMessage,
    })
    replyMessage.value = ''
    Message.success('回复成功')
    await loadTickets()
    await reloadDetailUntilMessage(sentMessage)
  } catch (error) {
    Message.error(getErrorMessage(error, '工单回复失败'))
  } finally {
    loading.reply = false
  }
}

watch(
  () => form.linked_trace_id,
  (traceId) => {
    if (!traceId) return
    const order = props.orders.find((item) => item.trace_id === traceId)
    if (!order) return
    if (!form.account) {
      form.account = order.account || ''
    }
    if (!form.school) {
      form.school = order.school_name || ''
    }
  },
)

watch(
  () => props.currentUserUid,
  (value) => {
    if (value > 0) {
      void loadTickets()
    }
  },
  { immediate: true },
)

watch(
  [tickets, () => props.isMobile],
  () => {
    const totalPages = Math.max(1, Math.ceil(tickets.value.length / mobileTicketPageSize))
    if (!props.isMobile) {
      ticketPage.value = 1
      return
    }
    if (ticketPage.value > totalPages) {
      ticketPage.value = totalPages
    }
  },
)

onMounted(() => {
  if (props.currentUserUid > 0) {
    void loadTickets()
  }
})
</script>

